using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionWithMinimumAstriumActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/BattleActionWithMinimumAstriumActionCustomDescription", order = 0)]
public class BattleActionWithMinimumAstriumActionCustomDescription : CustomBattleActionDescription
{
	private const string minimumAstriumDescriptionID = "MinAstrium";

	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	public PlayerEffectsList PlayerEffectsList => playerEffectsList;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		BattleActionWithMinimumAstriumAction battleActionWithMinimumAstriumAction = battleAction as BattleActionWithMinimumAstriumAction;
		string minimumAstriumDescription = GetMinimumAstriumDescription(battleActionWithMinimumAstriumAction, amountModified);
		BattleAction battleAction2 = battleActionWithMinimumAstriumAction.BattleAction;
		int fixedActionValue = battleActionWithMinimumAstriumAction.FixedActionValue;
		int amount = ((fixedActionValue > 0) ? fixedActionValue : GetAmountWithoutEquation(amountModified));
		int bonusAmount = ((fixedActionValue <= 0) ? GetBonusAmountWithoutEquation(amountModified) : 0);
		string actionDescription = battleAction2.GetActionDescription(amount, bonusAmount);
		string text = minimumAstriumDescription + "\n" + actionDescription;
		int astriumCost = battleActionWithMinimumAstriumAction.AstriumCost;
		if (astriumCost > 0 && !battleActionWithMinimumAstriumAction.DisableAstriumCostDescription)
		{
			string localizedDecreaseEffect = base.localizationManager.GetLocalizedDecreaseEffect(playerEffectsList.AstriumEffect, astriumCost);
			text = text + "\n" + localizedDecreaseEffect;
		}
		if (battleActionWithMinimumAstriumAction.EnableGainAstrium)
		{
			string actionDescription2 = battleActionWithMinimumAstriumAction.GainAstriumEffectAction.GetActionDescription(battleActionWithMinimumAstriumAction.GainAstriumAmount);
			text = text + "\n" + actionDescription2;
		}
		return text;
	}

	public string GetMinimumAstriumDescription(BattleActionWithMinimumAstriumAction battleActionWithMinimumAstriumAction, string amountModified)
	{
		int num = (battleActionWithMinimumAstriumAction.VariableMinimumAstriumAmount ? GetAmountWithoutEquation(amountModified) : battleActionWithMinimumAstriumAction.MinimumAstriumAmount);
		return Smart.Format(base.localizationManager.GetLocalizedString("MinAstrium"), num);
	}
}
